/**
 * This file implements a catch-all route that renders the user-facing pages
 * generated by Puck. For any route visited (with exception of other hardcoded
 * pages in /app), it will check your database (via `getPage`) for a Puck page
 * and render it using <Render>.
 *
 * All routes produced by this page are statically rendered using incremental
 * static site generation. After the first visit, the page will be cached as
 * a static file. Subsequent visits will receive the cache. Publishing a page
 * will invalidate the cache as the page is written in /api/puck/route.ts
 */

import { Metadata } from 'next';
import { getSeoData } from '../../../lib/seo';
import { Client } from './client';
import { notFound } from "next/navigation";
import { getPage } from "pageEditor/lib/get-page";
import { getTenantConfig } from '@config/tenant.config';

// Helper function to validate puck path pattern
function isValidPuckPath(puckPath: string[]): boolean {
    // Check if puckPath array is empty or undefined
    if (!puckPath || !Array.isArray(puckPath)) {
        return false;
    }
    
    // Check if any path segment contains dots (like com.chrome.devtools or file.json)
    return !puckPath.some(segment => segment.includes('.'));
}

interface PageProps {
  params: Promise<{
    puckPath: string[];
  }>;
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const config = getTenantConfig();
  const resolvedParams = await params;
  
  if (!isValidPuckPath(resolvedParams.puckPath)) {
    return {
      title: "Page Not Found",
      description: "The requested page could not be found",
    };
  }
  
  const slug = resolvedParams.puckPath ? `/${resolvedParams.puckPath.join('/')}` : '/';

  const seoData = getSeoData(slug);

  const baseUrl = process.env.NEXT_PUBLIC_WEBSITE_URL || '';
  const canonicalUrl = seoData?.metaTags?.canonical || `${baseUrl}${slug}`;

  // Generate structured data JSON-LD
  const structuredData = {
    "@context": "https://schema.org",
    "@type": seoData?.structuredData?.type,
    "name": seoData?.structuredData?.name || process.env.NEXT_PUBLIC_APP_NAME || "",
    "description": seoData?.structuredData?.description || process.env.NEXT_PUBLIC_APP_OG_DESC || "",
    "url": seoData?.structuredData?.url || process.env.NEXT_PUBLIC_WEBSITE_URL || "",
    "logo": seoData?.structuredData?.logo || config?.lightLogoUrl || config?.darkLogoUrl || "",
    "address": {
      "@type": "PostalAddress",
      "streetAddress": seoData?.structuredData?.address?.streetAddress,
      "addressLocality": seoData?.structuredData?.address?.addressLocality,
      "addressRegion": seoData?.structuredData?.address?.addressRegion,
      "postalCode": seoData?.structuredData?.address?.postalCode,
      "addressCountry": seoData?.structuredData?.address?.addressCountry
    },
    "telephone": seoData?.structuredData?.telephone || process.env.NEXT_PUBLIC_SUPPORT_PHONE || "",
    "email": seoData?.structuredData?.email || process.env.NEXT_PUBLIC_SUPPORT_EMAIL || "",
    "priceRange": seoData?.structuredData?.priceRange || "",
    "servesCuisine": seoData?.structuredData?.servesCuisine || [],
    "acceptsReservations": seoData?.structuredData?.acceptsReservations || "",
    "paymentAccepted": seoData?.structuredData?.paymentAccepted || []
  };

  return {
    title: seoData?.metaTags?.title,
    description: seoData?.metaTags?.description,
    keywords: seoData?.metaTags?.keywords,
    authors: [{ name: seoData?.metaTags?.author }],
    publisher: process.env.NEXT_PUBLIC_PUBLISHER_NAME || "",
    robots: seoData?.metaTags?.robots,
    viewport: seoData?.metaTags?.viewport,
    alternates: {
      canonical: canonicalUrl,
      languages: seoData?.additionalTags?.hreflang?.reduce((acc, item) => {
        acc[item?.hreflang] = item?.href;
        return acc;
      }, {} as Record<string, string>)
    },
    openGraph: {
      title: seoData?.openGraph?.title,
      description: seoData?.openGraph?.description,
      type: seoData?.openGraph?.type as 'website' | 'article' | 'book' | 'profile' | 'music.song' | 'music.album' | 'music.playlist' | 'music.radio_station' | 'video.movie' | 'video.episode' | 'video.tv_show' | 'video.other',
      url: seoData?.openGraph?.url || process.env.NEXT_PUBLIC_WEBSITE_URL || "",
      siteName: seoData?.openGraph?.siteName,
      locale: seoData?.openGraph?.locale,
      images: [
        {
          url: seoData?.openGraph?.image || config?.lightLogoUrl || config?.darkLogoUrl || "",
          alt: seoData?.openGraph?.imageAlt,
          width: parseInt(seoData?.openGraph?.imageWidth || '0'),
          height: parseInt(seoData?.openGraph?.imageHeight || '0'),
        },
      ],
    },
    twitter: {
      card: seoData?.twitterCard?.card as 'summary' | 'summary_large_image' | 'app' | 'player',
      site: seoData?.twitterCard?.site,
      creator: seoData?.twitterCard?.creator,
      title: seoData?.twitterCard?.title,
      description: seoData?.twitterCard?.description,
      images: [
        {
          url: seoData?.twitterCard?.image || config?.lightLogoUrl || config?.darkLogoUrl || "",
          alt: seoData?.twitterCard?.imageAlt,
        },
      ],
    },
    icons: {
      icon: seoData?.additionalTags?.favicon,
      apple: seoData?.additionalTags?.appleTouchIcon,
    },
    manifest: seoData.additionalTags.manifest,
    verification: {
      google: process.env.GOOGLE_SITE_VERIFICATION,
      yandex: process.env.YANDEX_VERIFICATION,
      yahoo: process.env.YAHOO_VERIFICATION,
    },
    category: 'food',
    classification: 'business',
    other: {
      'theme-color': seoData.additionalTags.themeColor,
      'apple-mobile-web-app-capable': 'yes',
      'apple-mobile-web-app-status-bar-style': 'default',
      'apple-mobile-web-app-title': seoData.metaTags.title,
      'application-name': seoData.metaTags.title,
      'msapplication-TileColor': seoData.additionalTags.themeColor,
      'msapplication-config': 'browserconfig.xml',
      'structured-data': JSON.stringify(structuredData),
    }
  };
}

export default async function PuckPage({ params }: PageProps) {
  const resolvedParams = await params;
  
  if (!isValidPuckPath(resolvedParams.puckPath)) {
    return notFound();
  }
  
  const slug = resolvedParams.puckPath ? `/${resolvedParams.puckPath.join('/')}` : '/';

  // If the slug is exactly "/puck", do not render content
  if (slug === "/puck") {
    return notFound();
  }

  // For all routes, check if they match store pattern
  // If they don't match store pattern, return notFound to prevent conflicts
  if (slug.includes('_')) {
    // This might be a store route, let other routes handle it
    return notFound();
  }

  // Load data from database for the route
  let data = getPage(slug);
  
  // If no data, create basic structure
  if (!data) {
    data = {
      content: [],
      root: {},
      zones: {}
    };
  }
  
  return <Client data={data} path={slug} />;
}

